"""Task execution helpers."""
import os, subprocess, sys, shlex, glob, hashlib, json
from templating import render, resolve_vars


def _subst(s, values):
    return render(s, values) if isinstance(s, str) else s


def _patterns(value):
    result=[]
    for item in value or []:
        if isinstance(item,str): result.append(item)
        elif isinstance(item,dict) and item.get('exclude') is None:
            result.extend(map(str,item.keys()))
    return result


def _file_signature(task, task_dir, root, name):
    sources=_patterns(task.get('sources'))
    generates=_patterns(task.get('generates'))
    if not sources or not generates:return None
    records=[]
    for pattern in sources+generates:
        paths=glob.glob(os.path.join(task_dir,pattern),recursive=True)
        if not paths: records.append((pattern,None)); continue
        for path in sorted(paths):
            try:
                with open(path,'rb') as f:
                    digest=hashlib.sha256(f.read()).hexdigest()
                records.append((os.path.relpath(path,root),digest))
            except OSError: records.append((path,None))
    return hashlib.sha256(json.dumps(records,separators=(',',':')).encode()).hexdigest()


